function validate([s]) {
  if (typeof s !== 'string') return 's must be a string.';
  if (s.length < 1 || s.length > 2000) return 's has 1 to 2000 characters.';
  if (!/^[a-z]+$/.test(s)) return 'Use lowercase English letters only.';
  return null;
}

