function minCut(s) {
  const n = s.length;
  const pal = Array.from({ length: n }, () => new Uint8Array(n));
  for (let j = 0; j < n; j++) {
    for (let i = j; i >= 0; i--) {
      pal[i][j] = s[i] === s[j] && (j - i < 2 || pal[i + 1][j - 1] === 1) ? 1 : 0;
    }
  }
  const pieces = new Array(n).fill(Infinity);
  for (let j = 0; j < n; j++) {
    for (let i = 0; i <= j; i++) {
      if (pal[i][j] === 1) pieces[j] = Math.min(pieces[j], (i === 0 ? 0 : pieces[i - 1]) + 1);
    }
  }
  return pieces[n - 1] - 1;
}

