function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const alphabets = ['a', 'ab', 'abc', 'abcdefghijklmnopqrstuvwxyz'];
  const alphabet = alphabets[int(0, alphabets.length - 1)];
  const n = size === 'large' ? int(1500, 2000) : int(1, 12);
  const letter = () => alphabet[int(0, alphabet.length - 1)];
  let s = '';
  if (rand() < 0.5) {
    // Glue random palindromes together so long palindromic pieces are common.
    while (s.length < n) {
      const half = int(0, size === 'large' ? 200 : 3);
      let part = '';
      for (let k = 0; k < half; k++) part += letter();
      const middle = rand() < 0.5 ? letter() : '';
      s += part + middle + part.split('').reverse().join('');
    }
    s = s.slice(0, n);
    if (s.length === 0) s = letter();
  } else {
    for (let k = 0; k < n; k++) s += letter();
  }
  return [s];
}
